import Foundation

/// Display width in terminal cells: ASCII is 1, CJK and emoji are 2, combining marks are 0.
///
/// `String.count` is the number of extended grapheme clusters, which is not what a terminal
/// draws: "访达" is two characters and four cells, and a window title with a Chinese app name
/// would push everything after it right, break every column in a panel, and truncate in the
/// middle of a glyph.
///
/// The numbers come from libghostty (`WidthTable.swift`, generated by `scripts/gen-widths.sh`), and
/// the reason is a disagreement that was invisible until it was measured on two terminals: the old
/// hand-written table was EastAsianWidth plus "emoji are wide", which says `☰` (U+2630) is one cell
/// and a flag is one cell — and both Ghostty 1.4.0 and Rex draw two. Every column after such a glyph
/// was then off by one, silently, and only for the glyphs nobody had thought about (issue #8 is the
/// original; `docs/design-ui-v2.zh-CN.md` §2.3 has the measurements).
///
/// The rule is the terminal's own (`ghostty_unicode_grapheme_width`, i.e. mode 2027 on), because
/// that is what draws the cell:
///
///   * a cluster starts at the width of its **first** codepoint;
///   * VS16 makes it two cells and VS15 makes it one — but only on a codepoint that is a valid
///     emoji variation sequence base; on anything else both are ignored (`⌚` is two cells, `⌚︎`
///     with VS15 is one, `⚙` is one and `⚙️` is two);
///   * any other codepoint that joins the cluster and is not zero-width-in-grapheme makes it two
///     (`👍🏽`, a flag's second regional indicator, a keycap's enclosing mark);
///   * everything else leaves it alone, so `e` + U+0301 is still one cell.
///
/// Segmentation is not re-done here: a `Character` is already a UAX #29 cluster, which is the same
/// question the terminal asks before it prints. A string is the sum over its characters.
enum DisplayWidth {
    /// Cells this scalar occupies, ignoring context. 0 = combining/joiner, 2 = wide.
    ///
    /// Control characters answer 1, not 0: every caller replaces them with a space before measuring
    /// (`truncate`), so "a control character is a cell" is the contract they rely on, and libghostty's
    /// own table answers 0 there because the terminal's print path never sees one.
    static func of(_ scalar: UnicodeScalar) -> Int {
        let v = scalar.value
        if v < 0x20 || (0x7F...0x9F).contains(v) { return 1 }
        if WidthTable.contains(WidthTable.wide, v) { return 2 }
        if WidthTable.contains(WidthTable.zero, v) { return 0 }
        return 1
    }

    /// Cells this cluster occupies — one glyph, however many codepoints it took.
    static func of(_ ch: Character) -> Int {
        var width = 0
        var prev: UInt32?
        for scalar in ch.unicodeScalars {
            let v = scalar.value
            if prev == nil {
                // The cluster starts at its first codepoint's width. A lone combining mark is
                // malformed at a cell start and measures 0, which is what the old table did too.
                width = of(scalar)
                prev = v
                continue
            }
            switch v {
            case 0xFE0F, 0xFE0E:
                // An invalid variation selector is *ignored entirely*, including as the previous
                // codepoint of the next comparison — the terminal does not store it in the cell, so
                // `⚙` + U+0301 + VS16 is still one cell (`prev` stays U+0301... which is not a base
                // either, so the selector is dropped).
                if let base = prev, WidthTable.contains(WidthTable.vsBase, base) {
                    width = v == 0xFE0F ? 2 : 1
                    prev = v
                }
            default:
                if WidthTable.contains(WidthTable.widens, v) { width = 2 }
                prev = v
            }
        }
        return width
    }

    static func of(_ s: String) -> Int {
        s.reduce(0) { $0 + of($1) }
    }

    /// Cut to at most `cells` columns without splitting a wide glyph, ending in an ellipsis when
    /// anything was dropped.
    ///
    /// Control characters are replaced with spaces first. Every caller is painting **a string the
    /// user does not control** -- a window title comes from whatever app owns the window -- and a
    /// title containing `\n` scrolls the grid the wall is positioned on, while one containing
    /// `ESC` could move the cursor or emit its own escape sequence (issue: the wall's "no newline"
    /// contract only held for text that had no newline).
    static func truncate(_ s: String, to cells: Int) -> String {
        guard cells > 0 else { return "" }
        let s = String(s.map { ch -> Character in
            let printable = ch.unicodeScalars.allSatisfy { $0.value >= 0x20 && $0.value != 0x7F }
            return printable ? ch : " "
        })
        var out = ""
        var used = 0
        var truncated = false
        for ch in s {
            let width = of(ch)
            if used + width > cells { truncated = true; break }
            out.append(ch)
            used += width
        }
        guard truncated else { return out }
        while used + 1 > cells, !out.isEmpty {
            if let last = out.popLast() { used -= of(last) }
        }
        return out + "…"
    }

    /// Exactly `cells` columns: truncated if too wide, space-padded if too narrow.
    static func pad(_ s: String, to cells: Int, alignRight: Bool = false) -> String {
        let body = truncate(s, to: cells)
        let used = of(body)
        guard used < cells else { return body }
        let fill = String(repeating: " ", count: cells - used)
        return alignRight ? fill + body : body + fill
    }

    /// Start column (0-based) that keeps an `width`-cell string right-aligned inside `cells`.
    static func rightAlignedStart(_ s: String, cells: Int) -> Int {
        max(0, cells - of(s))
    }
}

extension WidthTable {
    /// Is `cp` inside one of the flat `(start, end)` pairs? The generated tables are sorted and
    /// merged, so a binary search is the whole lookup — 877 ranges, and the widest table is 378.
    static func contains(_ pairs: [UInt32], _ cp: UInt32) -> Bool {
        var low = 0
        var high = pairs.count / 2 - 1
        while low <= high {
            let mid = (low + high) / 2
            if cp < pairs[mid * 2] {
                high = mid - 1
            } else if cp > pairs[mid * 2 + 1] {
                low = mid + 1
            } else {
                return true
            }
        }
        return false
    }
}
